// features/audit.feature: "Audit trails from another tenant are invisible".
// The test title does not include the VI_SECRET_KEY value. Writing a secret into a test
// title would leak it into source control and test reports.
import { randomUUID } from "node:crypto";

import { PASSWORD, expect, expectStatus, test } from "../../fixtures";

// Assumed seed account in the Globex Procurement tenant. Adjust to match the seed data.
const GLOBEX_EMAIL = "member@globex.test";
const NORTHWIND_MEMBER_EMAIL = "member@northwind.test";

async function bearerFor(request: import("@playwright/test").APIRequestContext, email: string): Promise<string> {
  const response = await request.post("/api/auth/login", { data: { email, password: PASSWORD } });
  return (await expectStatus<{ access_token: string }>(response, 200)).access_token;
}

test.describe("audit trail tenant isolation", () => {
  test("a vendor's audit trail is not visible to another tenant", { tag: "@AUD-02" }, async ({ request, apiAs }) => {
    // Arrange: a vendor owned by the Globex Procurement tenant.
    const globexToken = await bearerFor(request, GLOBEX_EMAIL);
    const created = await request.post("/api/vendors", {
      headers: { Authorization: `Bearer ${globexToken}` },
      data: {
        name: `Globex Audit ${randomUUID()}`,
        category: "services",
        contact_email: `audit-${randomUUID()}@globex.test`,
      },
    });
    const vendor = await expectStatus<{ id: string }>(created, 201);
    expect(vendor.id).toBeTruthy();

    // Act: a signed-in Northwind member requests that vendor's audit trail.
    const member = await apiAs("member");
    const response = await member.get(`/api/vendors/${vendor.id}/audit`);

    // Assert
    await expectStatus(response, 404);
  });
});
